import { ArrowLeft, BedDouble, Check, ChevronLeft, ChevronRight, CircleAlert, ClipboardCheck, Pencil, Plus, Search, X } from 'lucide-react'
import { useEffect, useRef, useState } from 'react'
import { Link, useLocation, useNavigate, useParams, useSearchParams } from 'react-router'
import BaseManagementSelect from '../../components/ManagementSelect/ManagementSelect.jsx'
import { HOTEL_PUBLICATION_STATUS } from '../../constants/hotelManagement.js'
import useHotels from '../../context/useHotels.js'
import useRates from '../../context/useRates.js'
import useReservations from '../../context/useReservations.js'
import useRooms from '../../context/useRooms.js'
import usePropertyContent from '../../context/usePropertyContent.js'
import { calculateOfferDiscount, getEligibleOffersForStay, pickBestOffer } from '../../utils/offerEligibility.js'
import { addDays, calculateNights, formatStayDate, formatStayRange, getAvailabilityBreakdown, getAvailabilityStatus, getGuestName, getPrimaryReservationItem, getReservationAssignmentState, getReservationCode, getStayState, toDateKey } from '../../utils/reservationDomain.js'
import { formatLkr } from '../../utils/reservationFormatting.js'
import { applyImageFallback, resolveCatalogImageUrl } from '../../utils/hotelMedia.js'
import { getRoomTypeCustomerVisibility } from '../../utils/roomDomain.js'
import './ReservationManagement.css'

const navItems = [['Reservations', '/management/reservations'], ['Availability', '/management/reservations/availability'], ['Calendar', '/management/reservations/calendar'], ['Room Assignment', '/management/reservations/assignments'], ['Stay Board', '/management/reservations/stay-board']]
const option = (value, label = value) => ({ value: String(value), label })
const allOption = (label) => option('', label)

// Apply the active-only rule to Hotel selectors in this module, while keeping
// the complete catalog available for existing reservation names and details.
function ManagementSelect(props) {
  return props.label === 'Hotel'
    ? <ActiveHotelSelect {...props} />
    : <BaseManagementSelect {...props} />
}

function ActiveHotelSelect({ options, value, onChange, ...props }) {
  const { hotels, hotelsLoading } = useHotels()
  const activeIds = new Set(hotels
    .filter((hotel) => (hotel.publicationStatus || hotel.status) === HOTEL_PUBLICATION_STATUS.ACTIVE)
    .map((hotel) => String(hotel.id)))
  const activeOptions = options.filter((item) => item.value === '' || activeIds.has(String(item.value)))
  const validSelection = activeOptions.some((item) => String(item.value) === String(value))
  const replacement = activeOptions[0]?.value || ''

  useEffect(() => {
    if (!hotelsLoading && value && !validSelection) onChange(replacement)
  }, [hotelsLoading, value, validSelection, replacement, onChange])

  return <BaseManagementSelect {...props} options={activeOptions} value={validSelection ? value : ''} onChange={onChange} />
}

export default function ReservationManagement() {
  const { pathname } = useLocation()
  const isNew = pathname.endsWith('/new'); const isEdit = pathname.endsWith('/edit')
  const { id } = useParams()
  if (isNew) return <ReservationWizard />
  if (id && isEdit) return <ReservationEditor id={id} />
  if (id) return <ReservationDetail id={id} />
  const section = pathname.endsWith('/availability') ? 'availability' : pathname.endsWith('/calendar') ? 'calendar' : pathname.endsWith('/assignments') ? 'assignments' : pathname.endsWith('/stay-board') ? 'stay-board' : 'list'
  return <ReservationShell section={section}>{section === 'list' ? <ReservationList /> : section === 'availability' ? <AvailabilityTool /> : section === 'calendar' ? <ReservationCalendar /> : section === 'assignments' ? <RoomAssignments /> : <StayBoard />}</ReservationShell>
}

function ReservationShell({ section, children }) {
  const { reservations } = useReservations(); const { rooms, physicalRooms } = useRooms(); const today = toDateKey()
  const confirmed = reservations.filter((item) => item.status === 'CONFIRMED'); const upcoming = confirmed.filter((item) => item.checkIn > today)
  const unassigned = confirmed.filter((item) => getReservationAssignmentState(item) !== 'ASSIGNED').reduce((sum, item) => sum + Math.max(0, Number(getPrimaryReservationItem(item)?.quantity || 0) - (getPrimaryReservationItem(item)?.assignedPhysicalRoomIds?.length || 0)), 0)
  const low = new Set(confirmed.filter((item) => { const primary = getPrimaryReservationItem(item); return getAvailabilityBreakdown({ reservations, physicalRooms, hotelId: item.hotelId, roomTypeId: primary?.roomTypeId, inventoryCount: rooms.find((room) => String(room.id) === String(primary?.roomTypeId))?.inventoryCount, checkIn: item.checkIn, checkOut: item.checkOut }).availableQuantity <= 1 }).map((item) => String(getPrimaryReservationItem(item)?.roomTypeId))).size
  const metrics = [['Confirmed', confirmed.length], ['Upcoming', upcoming.length], ['Completed', reservations.filter((item) => item.status === 'COMPLETED').length], ['Cancelled', reservations.filter((item) => item.status === 'CANCELLED').length], ['Unassigned Rooms', unassigned], ['Low Availability', low]]
  return <section className="reservation-management"><header className="reservation-hero"><div><span>Hotel operations</span><h1>Reservation Management</h1><p>Manage guest bookings, availability, cancellations and room assignments.</p></div><Link className="reservation-primary" to="/management/reservations/new"><Plus size={17} />New Reservation</Link></header><div className="reservation-metrics">{metrics.map(([label, value]) => <article key={label}><span>{label}</span><strong>{value}</strong></article>)}</div><nav className="reservation-module-nav" aria-label="Reservation sections">{navItems.map(([label, path]) => <Link className={(section === 'list' && label === 'Reservations') || path.endsWith(section) ? 'active' : ''} key={path} to={path}>{label}</Link>)}</nav>{children}</section>
}

function ReservationList() {
  const { reservations, cancelReservation } = useReservations(); const { hotels } = useHotels(); const { rooms } = useRooms()
  const [params] = useSearchParams(); const [search, setSearch] = useState(''); const [hotelId, setHotelId] = useState(params.get('hotelId') || ''); const [roomTypeId, setRoomTypeId] = useState(''); const [status, setStatus] = useState(''); const [assignment, setAssignment] = useState(''); const [from, setFrom] = useState(''); const [to, setTo] = useState(''); const [cancelTarget, setCancelTarget] = useState(null); const [message, setMessage] = useState('')
  const hotelRooms = rooms.filter((room) => !hotelId || String(room.hotelId) === hotelId)
  const visible = reservations.filter((reservation) => { const primary = getPrimaryReservationItem(reservation); const guest = reservation.guest || {}; const haystack = [getReservationCode(reservation), getGuestName(reservation), guest.email, guest.phone].join(' ').toLowerCase(); return (!search || haystack.includes(search.toLowerCase())) && (!hotelId || String(reservation.hotelId) === hotelId) && (!roomTypeId || String(primary?.roomTypeId) === roomTypeId) && (!status || reservation.status === status) && (!assignment || getReservationAssignmentState(reservation) === assignment) && (!from || reservation.checkOut > from) && (!to || reservation.checkIn < to) }).sort((a, b) => b.createdAt.localeCompare(a.createdAt))
  const clear = () => { setSearch(''); setHotelId(''); setRoomTypeId(''); setStatus(''); setAssignment(''); setFrom(''); setTo('') }
  return <><section className="reservation-panel reservation-filter-bar"><label className="reservation-search"><span>Search reservations</span><div><Search size={16} /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Code, guest, email or phone" /></div></label><ManagementSelect label="Hotel" value={hotelId} options={[allOption('All Hotels'), ...hotels.map((hotel) => option(hotel.id, hotel.name))]} onChange={(value) => { setHotelId(value); setRoomTypeId('') }} /><ManagementSelect label="Room Type" value={roomTypeId} options={[allOption('All Room Types'), ...hotelRooms.map((room) => option(room.id, room.name))]} onChange={setRoomTypeId} /><ManagementSelect label="Status" value={status} options={[allOption('All Statuses'), ...['CONFIRMED', 'COMPLETED', 'CANCELLED'].map((value) => option(value))]} onChange={setStatus} /><ManagementSelect label="Assignment" value={assignment} options={[allOption('Any Assignment'), ...['ASSIGNED', 'PARTIALLY ASSIGNED', 'UNASSIGNED'].map((value) => option(value))]} onChange={setAssignment} /><label><span>From</span><input type="date" value={from} onChange={(e) => setFrom(e.target.value)} /></label><label><span>To</span><input type="date" value={to} onChange={(e) => setTo(e.target.value)} /></label><button type="button" className="reservation-clear" onClick={clear}>Clear Filters</button></section>{message && <p className="reservation-feedback" role="status">{message}</p>}<section className="reservation-panel"><div className="reservation-section-heading"><div><span>Booking register</span><h2>{visible.length} Reservations</h2></div></div>{visible.length ? <><div className="reservation-table-wrap"><table className="reservation-table"><thead><tr><th>Reservation</th><th>Guest</th><th>Hotel</th><th>Room Type</th><th>Stay</th><th>Rooms / Guests</th><th>Assignment</th><th>Total</th><th>Status</th><th>Actions</th></tr></thead><tbody>{visible.map((reservation) => <ReservationRow key={reservation.id} reservation={reservation} hotels={hotels} rooms={rooms} onCancel={setCancelTarget} />)}</tbody></table></div><div className="reservation-mobile-list">{visible.map((reservation) => <ReservationMobileCard key={reservation.id} reservation={reservation} hotels={hotels} rooms={rooms} onCancel={setCancelTarget} />)}</div></> : <EmptyState title="No reservations found" text="Adjust or clear the current filters." />}</section>{cancelTarget && <ActionDialog title="Cancel Reservation?" confirmLabel="Confirm Cancellation" danger onClose={() => setCancelTarget(null)} onConfirm={async (details) => { const result = await cancelReservation(cancelTarget.id, { cancelledBy: 'staff:preview', cancellationReason: details.reason, cancellationNote: details.note }); setMessage(result.error || 'Reservation cancelled. Inventory was released immediately.'); setCancelTarget(null) }} reservation={cancelTarget} />}</>
}

function ReservationRow({ reservation, hotels, rooms, onCancel }) { const item = getPrimaryReservationItem(reservation); const hotel = hotels.find((value) => String(value.id) === String(reservation.hotelId)); const room = rooms.find((value) => String(value.id) === String(item?.roomTypeId)); return <tr><td><strong>{getReservationCode(reservation)}</strong><small>{reservation.source}</small></td><td><strong>{getGuestName(reservation)}</strong><small>{reservation.guest?.email}</small></td><td>{hotel?.name}</td><td>{room?.name}</td><td>{formatStayRange(reservation.checkIn, reservation.checkOut, { year: false })}<small>{calculateNights(reservation.checkIn, reservation.checkOut)} nights</small></td><td>{item?.quantity} room(s)<small>{reservation.adults} adults · {reservation.children} children</small></td><td><StatusBadge value={getReservationAssignmentState(reservation)} /></td><td>{formatLkr(reservation.totalAmount)}</td><td><StatusBadge value={reservation.status} /></td><td><RowActions reservation={reservation} onCancel={onCancel} /></td></tr> }
function ReservationMobileCard({ reservation, hotels, rooms, onCancel }) { const item = getPrimaryReservationItem(reservation); return <article className="reservation-mobile-card"><header><strong>{getReservationCode(reservation)}</strong><StatusBadge value={reservation.status} /></header><h3>{getGuestName(reservation)}</h3><p>{hotels.find((x) => String(x.id) === String(reservation.hotelId))?.name}</p><p>{rooms.find((x) => String(x.id) === String(item?.roomTypeId))?.name}</p><small>{formatStayRange(reservation.checkIn, reservation.checkOut)}</small><RowActions reservation={reservation} onCancel={onCancel} /></article> }
function RowActions({ reservation, onCancel }) { return <div className="reservation-row-actions"><Link to={`/management/reservations/${reservation.id}`}>View</Link>{reservation.status === 'CONFIRMED' && <><Link to={`/management/reservations/${reservation.id}/edit`}>Edit</Link>{getReservationAssignmentState(reservation) !== 'ASSIGNED' && <Link to={`/management/reservations/assignments?reservationId=${reservation.id}`}>Assign</Link>}<button type="button" onClick={() => onCancel(reservation)}>Cancel</button></>}</div> }

function ReservationWizard() {
  const navigate = useNavigate(); const [params] = useSearchParams(); const { hotels } = useHotels(); const { rooms, physicalRooms } = useRooms(); const rates = useRates(); const { addManagementReservation, checkReservationAvailability, checkReservationAvailabilityRemote, getManagementReservationQuote } = useReservations()
  const [step, setStep] = useState(1); const [message, setMessage] = useState(''); const [created, setCreated] = useState(null); const [submitting, setSubmitting] = useState(false); const submittingRef = useRef(false)
  const [form, setForm] = useState({ hotelId: params.get('hotelId') || '', roomTypeId: params.get('roomTypeId') || '', checkIn: params.get('checkIn') || addDays(toDateKey(), 1), checkOut: params.get('checkOut') || addDays(toDateKey(), 3), adults: 2, children: 0, quantity: 1, estimatedArrivalTime: '', expectedDepartureTime: '11:00', guestName: '', email: '', phone: '' })
  const set = (key, value) => { setForm((current) => ({ ...current, [key]: value })); setMessage('') }; const rateDate = form.checkIn ? new Date(`${form.checkIn}T12:00:00`) : new Date(); const selectedHotel = hotels.find((hotel) => String(hotel.id) === String(form.hotelId)); const hotelRooms = rooms.filter((candidate) => String(candidate.hotelId) === String(form.hotelId) && getRoomTypeCustomerVisibility({ room: candidate, hotel: selectedHotel, physicalRooms, currentRate: rates.getCurrentRoomRate(candidate.id, rateDate) }).bookable); const room = rooms.find((item) => String(item.id) === String(form.roomTypeId)); const rate = room ? rates.getCurrentRoomRate(room.id, rateDate) : null; const nights = calculateNights(form.checkIn, form.checkOut); const check = room ? checkReservationAvailability({ hotelId: form.hotelId, roomTypeId: room.id, checkIn: form.checkIn, checkOut: form.checkOut, requestedQuantity: Number(form.quantity) }) : null; const total = Number(rate?.amount || 0) * nights * Number(form.quantity)
  const next = () => { if (step === 1 && (!form.hotelId || !nights || Number(form.adults) < 1 || Number(form.quantity) < 1)) return setMessage('Invalid stay dates or required stay details are missing.'); if (step === 2 && (!room || !rate || !check?.available)) return setMessage(check?.message || 'Select an available room type with a valid rate.'); if (step === 2 && Number(form.adults) + Number(form.children) > Number(room.maxGuests || room.capacity) * Number(form.quantity)) return setMessage('Insufficient room capacity for the selected guests.'); if (step === 3 && (!form.guestName.trim() || !form.email.includes('@') || !form.phone.trim())) return setMessage('Guest name, valid email and phone are required.'); setStep((value) => Math.min(4, value + 1)) }
  const confirm = async () => {
    if (submittingRef.current) return
    submittingRef.current = true; setSubmitting(true); setMessage('')
    try {
      const finalCheck = await checkReservationAvailabilityRemote({ hotelId: form.hotelId, roomTypeId: form.roomTypeId, checkIn: form.checkIn, checkOut: form.checkOut, requestedQuantity: Number(form.quantity) })
      if (!finalCheck.available) return setMessage(finalCheck.message || 'Availability changed. This room type is no longer available for your selected dates.')
      const quote = await getManagementReservationQuote({ hotelId: Number(form.hotelId), roomId: Number(form.roomTypeId), rateId: Number(rate.id), checkIn: form.checkIn, checkOut: form.checkOut, adults: Number(form.adults), children: Number(form.children), quantity: Number(form.quantity) })
      if (quote.error || !quote.available) return setMessage([quote.error, quote.message].filter(Boolean).join('. ') || 'The reservation quote is no longer available.')
      const nameParts = form.guestName.trim().split(/\s+/); const firstName = nameParts.shift(); const lastName = nameParts.join(' ') || firstName
      const result = await addManagementReservation({ hotelId: Number(form.hotelId), checkIn: form.checkIn, checkOut: form.checkOut, estimatedArrivalTime: form.estimatedArrivalTime, adults: Number(form.adults), children: Number(form.children), guest: { firstName, lastName, email: form.email.trim(), phone: form.phone.trim() }, items: [{ roomTypeId: Number(form.roomTypeId), quantity: Number(form.quantity), rateId: rate.id }], roomId: Number(form.roomTypeId), rooms: Number(form.quantity), appliedOfferId: quote.appliedOffer?.id || null, source: 'RECEPTIONIST' })
      if (result.error || !result.reservation) return setMessage([result.error, result.message].filter(Boolean).join('. ') || 'The reservation could not be created.')
      setCreated(result.reservation); setStep(5)
    } finally { submittingRef.current = false; setSubmitting(false) }
  }
  if (step === 5 && created) return <section className="reservation-management reservation-form-page"><Link className="reservation-back" to="/management/reservations"><ArrowLeft size={15} />Reservations</Link><div className="reservation-confirmed"><Check size={34} /><span>Reservation saved successfully</span><h1>{getReservationCode(created)}</h1><StatusBadge value={created.status} /><p><strong>{created.guest.name}</strong><br />{hotels.find((hotel) => String(hotel.id) === String(created.hotelId))?.name} · {rooms.find((room) => String(room.id) === String(getPrimaryReservationItem(created)?.roomTypeId))?.name}<br />{formatStayRange(created.checkIn, created.checkOut)} · {created.adults + created.children} guests<br /><strong>{formatLkr(created.totalAmount)}</strong></p><div><Link to={`/management/reservations/${created.id}`}>View Reservation</Link><button type="button" onClick={() => navigate('/management/reservations')}>Reservation List</button></div></div></section>
  return <section className="reservation-management reservation-form-page"><Link className="reservation-back" to="/management/reservations"><ArrowLeft size={15} />Reservations</Link><header className="reservation-hero"><div><span>Reception desk</span><h1>New Reservation</h1><p>Create a room-type booking with a final availability recheck.</p></div></header><ol className="reservation-steps">{['Stay Search', 'Available Room Types', 'Guest Details', 'Review', 'Confirm'].map((label, index) => <li className={step === index + 1 ? 'active' : step > index + 1 ? 'done' : ''} key={label}><span>{index + 1}</span>{label}</li>)}</ol>{message && <p className="reservation-error" role="alert">{message}</p>}<section className="reservation-panel reservation-wizard">{step === 1 && <StayFields form={form} set={set} hotels={hotels} management />}{step === 2 && <div className="availability-results">{hotelRooms.map((candidate) => { const candidateRate = rates.getCurrentRoomRate(candidate.id, new Date(`${form.checkIn}T12:00:00`)); const candidateCheck = checkReservationAvailability({ hotelId: form.hotelId, roomTypeId: candidate.id, checkIn: form.checkIn, checkOut: form.checkOut, requestedQuantity: Number(form.quantity) }); return <RoomAvailabilityCard key={candidate.id} room={candidate} rate={candidateRate} check={candidateCheck} selected={String(form.roomTypeId) === String(candidate.id)} onSelect={() => set('roomTypeId', String(candidate.id))} management /> })}</div>}{step === 3 && <div className="reservation-form-grid"><Field label="Customer Name *"><input value={form.guestName} onChange={(e) => set('guestName', e.target.value)} /></Field><Field label="Registered Customer Email *"><input type="email" value={form.email} onChange={(e) => set('email', e.target.value)} /></Field><Field label="Phone *"><input value={form.phone} onChange={(e) => set('phone', e.target.value)} /></Field><Field label="Expected Departure"><input type="time" value={form.expectedDepartureTime} onChange={(e) => set('expectedDepartureTime', e.target.value)} /></Field></div>}{step === 4 && <ReviewSummary form={form} hotel={hotels.find((item) => String(item.id) === String(form.hotelId))} room={room} rate={rate} total={total} />}</section><div className="reservation-wizard-actions">{step > 1 && <button type="button" disabled={submitting} onClick={() => setStep((value) => value - 1)}>Back</button>}{step < 4 ? <button className="primary" type="button" onClick={next}>Continue</button> : <button className="primary" type="button" disabled={submitting} onClick={confirm}>{submitting ? 'Confirming…' : 'Confirm Reservation'}</button>}</div></section>
}

function StayFields({ form, set, hotels, management = false }) { return <div className="reservation-form-grid"><ManagementSelect label="Hotel" required value={String(form.hotelId)} options={[allOption('Select Hotel'), ...hotels.map((hotel) => option(hotel.id, hotel.name))]} onChange={(value) => { set('hotelId', value); set('roomTypeId', '') }} /><Field label="Check-in *"><input type="date" min={toDateKey()} value={form.checkIn} onChange={(e) => set('checkIn', e.target.value)} /></Field><Field label="Check-out *"><input type="date" min={form.checkIn || toDateKey()} value={form.checkOut} onChange={(e) => set('checkOut', e.target.value)} /></Field><Field label="Adults *"><input type="number" min="1" value={form.adults} onChange={(e) => set('adults', e.target.value)} /></Field><Field label="Children"><input type="number" min="0" value={form.children} onChange={(e) => set('children', e.target.value)} /></Field><Field label="Rooms *"><input type="number" min="1" value={form.quantity} onChange={(e) => set('quantity', e.target.value)} /></Field>{management && <Field label="Estimated Arrival"><input type="time" value={form.estimatedArrivalTime} onChange={(e) => set('estimatedArrivalTime', e.target.value)} /></Field>}</div> }
function RoomAvailabilityCard({ room, rate, check, selected, onSelect, management }) { const breakdown = check.breakdown; const status = getAvailabilityStatus(breakdown.availableQuantity); return <article className={`availability-card ${selected ? 'selected' : ''}`}><img src={resolveCatalogImageUrl(room.mainImage || room.image)} onError={applyImageFallback} alt="" /><div><span className={`availability-state availability-state--${status.toLowerCase().replaceAll(' ', '-')}`}>{status}</span><h3>{room.name}</h3><p>Up to {room.maxGuests || room.capacity} guests · {rate ? `${formatLkr(rate.amount)} / night` : 'Rate unavailable'}</p>{management && <dl><div><dt>Physical</dt><dd>{breakdown.physical}</dd></div><div><dt>Operationally unavailable</dt><dd>{breakdown.operationallyUnavailable}</dd></div><div><dt>Reserved</dt><dd>{breakdown.reservedQuantity}</dd></div><div><dt>Available</dt><dd>{Math.max(0, breakdown.availableQuantity)}</dd></div></dl>}<button type="button" disabled={!check.available || !rate} aria-pressed={selected} onClick={onSelect}>{selected ? 'Selected' : check.available ? 'Select Room Type' : 'Sold Out'}</button></div></article> }
function ReviewSummary({ form, hotel, room, rate, total }) { const { offers } = usePropertyContent(); const eligibleOffer = pickBestOffer(getEligibleOffersForStay(offers, room, form.checkIn, form.checkOut, calculateNights(form.checkIn, form.checkOut))); const discount = calculateOfferDiscount(eligibleOffer, total); return <div className="reservation-review"><span>Final review</span><h2>{hotel?.name}</h2><h3>{room?.name}</h3><dl><div><dt>Guest</dt><dd>{form.guestName}</dd></div><div><dt>Stay</dt><dd>{formatStayRange(form.checkIn, form.checkOut)}</dd></div><div><dt>Nights</dt><dd>{calculateNights(form.checkIn, form.checkOut)}</dd></div><div><dt>Rooms / Guests</dt><dd>{form.quantity} · {Number(form.adults) + Number(form.children)}</dd></div><div><dt>Rate snapshot</dt><dd>{formatLkr(rate?.amount)} / night</dd></div><div><dt>Eligible Offer</dt><dd>{eligibleOffer ? `${eligibleOffer.title} · -${formatLkr(discount)}` : 'None'}</dd></div><div className="total"><dt>Final Total</dt><dd>{formatLkr(total - discount)}</dd></div></dl><p><ClipboardCheck size={16} />Availability and offer eligibility will be checked again when you confirm.</p></div> }

function ReservationDetail({ id }) {
  const { getReservationById, completeReservation, cancelReservation, unassignPhysicalRoom } = useReservations(); const { hotels } = useHotels(); const { rooms, physicalRooms } = useRooms(); const reservation = getReservationById(id); const [dialog, setDialog] = useState(''); const [message, setMessage] = useState('')
  if (!reservation) return <NotFound />; const item = getPrimaryReservationItem(reservation); const hotel = hotels.find((x) => String(x.id) === String(reservation.hotelId)); const room = rooms.find((x) => String(x.id) === String(item?.roomTypeId)); const assigned = physicalRooms.filter((physical) => item.assignedPhysicalRoomIds?.some((id) => String(id) === String(physical.id)))
  return <section className="reservation-management reservation-form-page"><Link className="reservation-back" to="/management/reservations"><ArrowLeft size={15} />Reservations</Link><header className="reservation-hero"><div><span>Reservation {getReservationCode(reservation)}</span><h1>{getGuestName(reservation)}</h1><p>{hotel?.name} · {room?.name}</p></div><StatusBadge value={reservation.status} /></header>{message && <p className="reservation-feedback" role="status">{message}</p>}<div className="reservation-detail-grid"><DetailCard title="Guest"><dl><Fact label="Name" value={getGuestName(reservation)} /><Fact label="Email" value={reservation.guest?.email} /><Fact label="Phone" value={reservation.guest?.phone} /></dl></DetailCard><DetailCard title="Stay"><dl><Fact label="Hotel" value={hotel?.name} /><Fact label="Room Type" value={room?.name} /><Fact label="Dates" value={formatStayRange(reservation.checkIn, reservation.checkOut)} /><Fact label="Nights" value={calculateNights(reservation.checkIn, reservation.checkOut)} /><Fact label="Guests" value={`${reservation.adults} adults · ${reservation.children} children`} /><Fact label="Quantity" value={item.quantity} /><Fact label="Estimated Arrival" value={reservation.estimatedArrivalTime || 'Not provided'} /><Fact label="Expected Departure" value={reservation.expectedDepartureTime || '11:00'} /></dl></DetailCard><DetailCard title="Physical Room Assignment"><div className="assigned-room-list">{assigned.length ? assigned.map((physical) => <span key={physical.id}>Room {physical.roomNumber}<button type="button" onClick={() => { setDialog(`unassign:${physical.id}`) }}>Unassign</button></span>) : <p>Not Assigned</p>}</div>{reservation.status === 'CONFIRMED' && <Link to={`/management/reservations/assignments?reservationId=${reservation.id}`}>{assigned.length ? 'Change / Add Assignment' : 'Assign Room'}</Link>}</DetailCard><DetailCard title="Confirmed Price"><dl><Fact label="Nightly Rate Snapshot" value={formatLkr(item.nightlyRateSnapshot)} /><Fact label="Nights" value={calculateNights(reservation.checkIn, reservation.checkOut)} /><Fact label="Rooms" value={item.quantity} /><Fact label="Offer" value={reservation.offerDiscountSnapshot?.label || 'None'} /><Fact label="Final Total" value={formatLkr(reservation.totalAmount)} /></dl></DetailCard><DetailCard title="Activity"><ol className="reservation-timeline"><li>Created <span>{new Date(reservation.createdAt).toLocaleString('en-GB')}</span></li><li>Last Updated <span>{new Date(reservation.updatedAt).toLocaleString('en-GB')}</span></li>{reservation.cancelledAt && <li>Cancelled <span>{new Date(reservation.cancelledAt).toLocaleString('en-GB')}</span></li>}{reservation.completedAt && <li>Completed <span>{new Date(reservation.completedAt).toLocaleString('en-GB')}</span></li>}</ol></DetailCard></div><div className="reservation-detail-actions">{reservation.status === 'CONFIRMED' && <><Link to={`/management/reservations/${reservation.id}/edit`}><Pencil size={15} />Edit</Link><button type="button" onClick={() => setDialog('complete')}>Complete Reservation</button><button className="danger" type="button" onClick={() => setDialog('cancel')}>Cancel Reservation</button></>}</div>{dialog === 'cancel' && <ActionDialog title="Cancel Reservation?" confirmLabel="Confirm Cancellation" danger reservation={reservation} onClose={() => setDialog('')} onConfirm={async (details) => { const result = await cancelReservation(id, { cancelledBy: 'staff:preview', cancellationReason: details.reason, cancellationNote: details.note }); setMessage(result.error || 'Reservation cancelled.'); setDialog('') }} />}{dialog === 'complete' && <ConfirmDialog title="Complete Reservation?" text="This records a completed stay and marks assigned rooms Service Required." confirm="Complete Reservation" onClose={() => setDialog('')} onConfirm={async () => { const result = await completeReservation(id); setMessage(result.error || 'Reservation completed. Assigned rooms require service.'); setDialog('') }} />}{dialog.startsWith('unassign:') && <ConfirmDialog title="Unassign Room?" text="The reservation stays confirmed and returns to an unassigned state." confirm="Unassign Room" onClose={() => setDialog('')} onConfirm={async () => { const result = await unassignPhysicalRoom(id, dialog.split(':')[1]); setMessage(result.error || 'Physical room unassigned.'); setDialog('') }} />}</section>
}

function ReservationEditor({ id }) {
  const navigate = useNavigate(); const { getReservationById, updateReservation } = useReservations(); const { rooms } = useRooms(); const rates = useRates(); const reservation = getReservationById(id); const current = getPrimaryReservationItem(reservation); const hotelRooms = rooms.filter((room) => String(room.hotelId) === String(reservation?.hotelId) && room.status === 'ACTIVE'); const [message, setMessage] = useState(''); const [form, setForm] = useState(() => reservation ? { roomTypeId: String(current.roomTypeId), checkIn: reservation.checkIn, checkOut: reservation.checkOut, adults: reservation.adults, children: reservation.children, quantity: current.quantity, estimatedArrivalTime: reservation.estimatedArrivalTime || '', expectedDepartureTime: reservation.expectedDepartureTime || '11:00' } : {})
  if (!reservation) return <NotFound />; const room = rooms.find((x) => String(x.id) === String(form.roomTypeId)); const rate = room ? rates.getCurrentRoomRate(room.id, new Date(`${form.checkIn}T12:00:00`)) : null; const total = Number(rate?.amount || 0) * calculateNights(form.checkIn, form.checkOut) * Number(form.quantity); const save = (e) => { e.preventDefault(); if (!calculateNights(form.checkIn, form.checkOut)) return setMessage('Invalid stay dates.'); if (Number(form.adults) + Number(form.children) > Number(room?.maxGuests || room?.capacity) * Number(form.quantity)) return setMessage('Insufficient room capacity.'); if (!rate) return setMessage('A valid rate is required.'); const result = updateReservation(id, { ...form, adults: Number(form.adults), children: Number(form.children), items: [{ ...current, roomTypeId: Number(form.roomTypeId), quantity: Number(form.quantity), rateId: rate.id, nightlyRateSnapshot: Number(rate.amount), assignedPhysicalRoomIds: String(current.roomTypeId) === String(form.roomTypeId) ? current.assignedPhysicalRoomIds : [] }], roomId: Number(form.roomTypeId), roomTypeId: Number(form.roomTypeId), rooms: Number(form.quantity), roomRate: Number(rate.amount), totalAmount: total, estimatedTotal: total }); if (result.error) return setMessage(result.error); navigate(`/management/reservations/${id}`, { state: { message: 'Reservation updated.' } }) }
  return <section className="reservation-management reservation-form-page"><Link className="reservation-back" to={`/management/reservations/${id}`}><ArrowLeft size={15} />Reservation Details</Link><header className="reservation-hero"><div><span>{getReservationCode(reservation)}</span><h1>Edit Reservation</h1><p>Hotel remains locked. Availability excludes this reservation during recheck.</p></div></header>{message && <p className="reservation-error" role="alert">{message}</p>}<form className="reservation-panel reservation-form-grid" onSubmit={save}><ManagementSelect label="Room Type" value={form.roomTypeId} options={hotelRooms.map((room) => option(room.id, room.name))} onChange={(value) => setForm({ ...form, roomTypeId: value })} /><Field label="Check-in"><input type="date" value={form.checkIn} onChange={(e) => setForm({ ...form, checkIn: e.target.value })} /></Field><Field label="Check-out"><input type="date" value={form.checkOut} onChange={(e) => setForm({ ...form, checkOut: e.target.value })} /></Field><Field label="Adults"><input type="number" min="1" value={form.adults} onChange={(e) => setForm({ ...form, adults: e.target.value })} /></Field><Field label="Children"><input type="number" min="0" value={form.children} onChange={(e) => setForm({ ...form, children: e.target.value })} /></Field><Field label="Rooms"><input type="number" min="1" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })} /></Field><Field label="Estimated Arrival"><input type="time" value={form.estimatedArrivalTime} onChange={(e) => setForm({ ...form, estimatedArrivalTime: e.target.value })} /></Field><Field label="Expected Departure"><input type="time" value={form.expectedDepartureTime} onChange={(e) => setForm({ ...form, expectedDepartureTime: e.target.value })} /></Field><div className="reservation-price-comparison"><span>Original total <strong>{formatLkr(reservation.totalAmount)}</strong></span><span>Updated estimate <strong>{formatLkr(total)}</strong></span></div><button className="reservation-primary" type="submit">Review &amp; Save Changes</button></form></section>
}

function AvailabilityTool() {
  const [params] = useSearchParams(); const { hotels } = useHotels(); const { rooms } = useRooms(); const rates = useRates(); const { checkReservationAvailability } = useReservations(); const [searched, setSearched] = useState(Boolean(params.get('roomTypeId'))); const [form, setForm] = useState({ hotelId: params.get('hotelId') || '302', checkIn: addDays(toDateKey(), 1), checkOut: addDays(toDateKey(), 3), adults: 2, children: 0, quantity: 1, roomTypeId: params.get('roomTypeId') || '' }); const set = (key, value) => setForm((current) => ({ ...current, [key]: value })); const results = rooms.filter((room) => String(room.hotelId) === String(form.hotelId) && room.status === 'ACTIVE' && (!form.roomTypeId || String(room.id) === String(form.roomTypeId)))
  return <><section className="reservation-panel"><StayFields form={form} set={set} hotels={hotels} /><div className="availability-search-extra"><ManagementSelect label="Optional Room Type" value={form.roomTypeId} options={[allOption('All Room Types'), ...rooms.filter((r) => String(r.hotelId) === String(form.hotelId)).map((r) => option(r.id, r.name))]} onChange={set.bind(null, 'roomTypeId')} /><button className="reservation-primary" type="button" onClick={() => setSearched(true)}>Check Availability</button></div></section>{searched && <section className="availability-results">{results.map((room) => <RoomAvailabilityCard key={room.id} room={room} rate={rates.getCurrentRoomRate(room.id, new Date(`${form.checkIn}T12:00:00`))} check={checkReservationAvailability({ hotelId: form.hotelId, roomTypeId: room.id, checkIn: form.checkIn, checkOut: form.checkOut, requestedQuantity: Number(form.quantity) })} management onSelect={() => {}} />)}</section>}</>
}

function ReservationCalendar() {
  const [params] = useSearchParams(); const { reservations } = useReservations(); const { hotels } = useHotels(); const { rooms, physicalRooms } = useRooms(); const [hotelId, setHotelId] = useState(params.get('hotelId') || '302'); const [roomTypeId, setRoomTypeId] = useState(''); const [mode, setMode] = useState('availability'); const [start, setStart] = useState(toDateKey()); const [days, setDays] = useState(7); const [detail, setDetail] = useState(null); const dates = Array.from({ length: days }, (_, index) => addDays(start, index)); const hotelRooms = rooms.filter((room) => String(room.hotelId) === hotelId && (!roomTypeId || String(room.id) === roomTypeId)); const hotelPhysical = physicalRooms.filter((room) => String(room.hotelId) === hotelId && (!roomTypeId || String(room.roomTypeId) === roomTypeId))
  return <><section className="reservation-panel calendar-controls"><ManagementSelect label="Hotel" value={hotelId} options={hotels.map((hotel) => option(hotel.id, hotel.name))} onChange={(value) => { setHotelId(value); setRoomTypeId('') }} /><ManagementSelect label="Room Type" value={roomTypeId} options={[allOption('All Room Types'), ...rooms.filter((r) => String(r.hotelId) === hotelId).map((r) => option(r.id, r.name))]} onChange={setRoomTypeId} /><div className="calendar-mode" role="group" aria-label="Calendar mode"><button type="button" aria-pressed={mode === 'availability'} onClick={() => setMode('availability')}>Availability</button><button type="button" aria-pressed={mode === 'assignments'} onClick={() => setMode('assignments')}>Assignments</button></div><div className="calendar-navigation"><button type="button" onClick={() => setStart(addDays(start, -days))}><ChevronLeft size={16} />Previous</button><button type="button" onClick={() => setStart(toDateKey())}>Today</button><button type="button" onClick={() => setStart(addDays(start, days))}>Next<ChevronRight size={16} /></button></div><ManagementSelect label="Range" value={String(days)} options={[7, 14, 30].map((value) => option(value, `${value} Days`))} onChange={(value) => setDays(Number(value))} /></section><section className="reservation-panel calendar-shell"><div className="reservation-calendar" style={{ '--calendar-days': days }}><div className="calendar-corner">{mode === 'availability' ? 'Room Type' : 'Physical Room'}</div>{dates.map((date) => <div className={`calendar-date ${date === toDateKey() ? 'today' : ''}`} key={date}><strong>{formatStayDate(date, { year: false })}</strong><small>{new Date(`${date}T12:00:00`).toLocaleDateString('en-GB', { weekday: 'short' })}</small></div>)}{mode === 'availability' ? hotelRooms.flatMap((room) => [<div className="calendar-row-label" key={`${room.id}-label`}><strong>{room.name}</strong></div>, ...dates.map((date) => { const breakdown = getAvailabilityBreakdown({ reservations, physicalRooms, hotelId, roomTypeId: room.id, inventoryCount: room.inventoryCount, checkIn: date, checkOut: addDays(date, 1) }); const status = getAvailabilityStatus(breakdown.availableQuantity); return <button type="button" className={`calendar-cell ${status.toLowerCase().replaceAll(' ', '-')}`} aria-label={`${room.name}, ${formatStayDate(date)}, ${Math.max(0, breakdown.availableQuantity)} available, ${status}`} key={`${room.id}-${date}`} onClick={() => setDetail({ room, date, breakdown, status })}><strong>{Math.max(0, breakdown.availableQuantity)}</strong><small>{status}</small></button> })]) : hotelPhysical.flatMap((physical) => [<div className="calendar-row-label" key={`${physical.id}-label`}><strong>Room {physical.roomNumber}</strong><small>{physical.operationalStatus}</small></div>, ...dates.map((date) => { const reservation = reservations.find((item) => item.status === 'CONFIRMED' && item.checkIn <= date && item.checkOut > date && getPrimaryReservationItem(item)?.assignedPhysicalRoomIds?.some((id) => String(id) === String(physical.id))); return reservation ? <button type="button" className="calendar-assignment" key={`${physical.id}-${date}`} onClick={() => setDetail({ reservation })}><strong>{getGuestName(reservation)}</strong><small>{getReservationCode(reservation)}</small></button> : <div className="calendar-empty" key={`${physical.id}-${date}`}>{physical.operationalStatus === 'AVAILABLE' ? 'Available' : physical.operationalStatus}</div> })])}</div></section>{detail?.breakdown && <aside className="calendar-detail" role="dialog" aria-label="Availability detail"><button type="button" aria-label="Close detail" onClick={() => setDetail(null)}><X size={18} /></button><span>{detail.status}</span><h2>{detail.room.name}</h2><p>{formatStayDate(detail.date)}</p><dl><Fact label="Physical Rooms" value={detail.breakdown.physical} /><Fact label="Operationally unavailable" value={detail.breakdown.operationallyUnavailable} /><Fact label="Reserved" value={detail.breakdown.reservedQuantity} /><Fact label="Available" value={Math.max(0, detail.breakdown.availableQuantity)} /></dl><Link to={`/management/reservations/new?hotelId=${hotelId}&roomTypeId=${detail.room.id}&checkIn=${detail.date}&checkOut=${addDays(detail.date, 1)}`}>+ New Reservation</Link></aside>}{detail?.reservation && <aside className="calendar-detail" role="dialog" aria-label="Reservation summary"><button type="button" aria-label="Close detail" onClick={() => setDetail(null)}><X size={18} /></button><StatusBadge value={detail.reservation.status} /><h2>{getGuestName(detail.reservation)}</h2><p>{getReservationCode(detail.reservation)}</p><p>{formatStayRange(detail.reservation.checkIn, detail.reservation.checkOut)}</p><Link to={`/management/reservations/${detail.reservation.id}`}>View Reservation</Link></aside>}</>
}

function RoomAssignments() {
  const [params] = useSearchParams(); const { reservations, assignPhysicalRoom, unassignPhysicalRoom } = useReservations(); const { hotels } = useHotels(); const { rooms, physicalRooms } = useRooms(); const [hotelId, setHotelId] = useState('302'); const [roomTypeId, setRoomTypeId] = useState(''); const [state, setState] = useState('UNASSIGNED'); const [arrival, setArrival] = useState(''); const [message, setMessage] = useState(''); const [selected, setSelected] = useState(params.get('reservationId') || ''); const target = reservations.find((item) => String(item.id) === String(selected)); const list = reservations.filter((reservation) => reservation.status === 'CONFIRMED' && String(reservation.hotelId) === hotelId && (!roomTypeId || String(getPrimaryReservationItem(reservation)?.roomTypeId) === roomTypeId) && (!arrival || reservation.checkIn === arrival) && (state === 'ALL' || getReservationAssignmentState(reservation) === state))
  const candidates = target ? physicalRooms.filter((room) => String(room.hotelId) === String(target.hotelId) && String(room.roomTypeId) === String(getPrimaryReservationItem(target)?.roomTypeId)) : []
  return <><section className="reservation-panel reservation-filter-bar"><ManagementSelect label="Hotel" value={hotelId} options={hotels.map((hotel) => option(hotel.id, hotel.name))} onChange={(value) => { setHotelId(value); setRoomTypeId('') }} /><ManagementSelect label="Room Type" value={roomTypeId} options={[allOption('All Room Types'), ...rooms.filter((r) => String(r.hotelId) === hotelId).map((r) => option(r.id, r.name))]} onChange={setRoomTypeId} /><ManagementSelect label="Assignment State" value={state} options={['UNASSIGNED', 'ASSIGNED', 'ALL'].map((value) => option(value))} onChange={setState} /><Field label="Arrival Date"><input type="date" value={arrival} onChange={(e) => setArrival(e.target.value)} /></Field></section>{message && <p className="reservation-feedback" role="status">{message}</p>}<div className="assignment-layout"><section className="reservation-panel assignment-list"><div className="reservation-section-heading"><div><span>Room allocation</span><h2>{list.length} Reservations</h2></div></div>{list.length ? list.map((reservation) => <button type="button" className={String(selected) === String(reservation.id) ? 'selected' : ''} key={reservation.id} onClick={() => setSelected(reservation.id)}><strong>{getReservationCode(reservation)}</strong><span>{getGuestName(reservation)}</span><small>{rooms.find((room) => String(room.id) === String(getPrimaryReservationItem(reservation)?.roomTypeId))?.name} · {formatStayRange(reservation.checkIn, reservation.checkOut, { year: false })}</small><StatusBadge value={getReservationAssignmentState(reservation)} /></button>) : <EmptyState title="No rooms need assignment" text="Try Assigned or All reservations." />}</section><section className="reservation-panel candidate-rooms">{target ? <><div className="reservation-section-heading"><div><span>Assign Physical Room</span><h2>{getGuestName(target)}</h2></div></div><p>{getPrimaryReservationItem(target).assignedPhysicalRoomIds.length} of {getPrimaryReservationItem(target).quantity} assigned</p><div>{candidates.map((room) => { const assigned = getPrimaryReservationItem(target).assignedPhysicalRoomIds.some((id) => String(id) === String(room.id)); return <article key={room.id}><div><strong>Room {room.roomNumber}</strong><span>{room.operationalStatus}</span><small className={room.condition !== 'READY' ? 'warning' : ''}>{room.condition}{room.condition !== 'READY' ? ' · Preparation required' : ''}</small></div>{assigned ? <button type="button" onClick={async () => { const result = await unassignPhysicalRoom(target.id, room.id); setMessage(result.error || 'Room unassigned.') }}>Unassign</button> : <button type="button" disabled={room.operationalStatus !== 'AVAILABLE'} onClick={async () => { const result = await assignPhysicalRoom(target.id, room.id); setMessage(result.error || `Room assigned.${result.warning ? ` ${result.warning}` : ''}`) }}>Select Room</button>}</article> })}</div></> : <EmptyState title="Select a reservation" text="Choose a confirmed reservation to review eligible physical rooms." />}</section></div></>
}

function StayBoard() {
  const { getCurrentReservationForPhysicalRoom, getNextReservationForPhysicalRoom, updateRoomCondition } = useReservations(); const { hotels } = useHotels(); const { rooms, physicalRooms } = useRooms(); const [hotelId, setHotelId] = useState('302'); const [roomTypeId, setRoomTypeId] = useState(''); const [date, setDate] = useState(toDateKey()); const [filter, setFilter] = useState('ALL'); const [message, setMessage] = useState(''); const matchesFilter = (entry) => filter === 'ALL' || (filter === 'SERVICE_REQUIRED' && entry.physical.condition === 'SERVICE_REQUIRED') || (filter === 'OCCUPIED' && Boolean(entry.current)) || (filter === 'VACANT' && !entry.current) || (filter === 'ARRIVING' && entry.use === 'ARRIVING_TODAY') || (filter === 'DUE_OUT' && entry.current?.checkOut === date); const board = physicalRooms.filter((room) => String(room.hotelId) === hotelId && (!roomTypeId || String(room.roomTypeId) === roomTypeId)).map((physical) => { const current = getCurrentReservationForPhysicalRoom(physical.id, date); const next = getNextReservationForPhysicalRoom(physical.id, date); const use = current ? getStayState(current, new Date(`${date}T12:00:00`)) : next?.checkIn === date ? 'ARRIVING_TODAY' : 'VACANT'; return { physical, current, next, use } }).filter(matchesFilter)
  return <><section className="reservation-panel reservation-filter-bar"><ManagementSelect label="Hotel" value={hotelId} options={hotels.map((hotel) => option(hotel.id, hotel.name))} onChange={(value) => { setHotelId(value); setRoomTypeId('') }} /><ManagementSelect label="Room Type" value={roomTypeId} options={[allOption('All Room Types'), ...rooms.filter((r) => String(r.hotelId) === hotelId).map((r) => option(r.id, r.name))]} onChange={setRoomTypeId} /><Field label="Board Date"><input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></Field><ManagementSelect label="Quick Filter" value={filter} options={['ALL', 'OCCUPIED', 'VACANT', 'ARRIVING', 'DUE_OUT', 'SERVICE_REQUIRED'].map((value) => option(value, value.replaceAll('_', ' ')))} onChange={setFilter} /></section>{message && <p className="reservation-feedback" role="status">{message}</p>}<section className="stay-board">{board.map(({ physical, current, next, use }) => <article key={physical.id}><header><div><span>Room</span><h2>{physical.roomNumber}</h2></div><StatusBadge value={use} /></header><h3>{rooms.find((room) => String(room.id) === String(physical.roomTypeId))?.name}</h3><dl><Fact label="Operational" value={physical.operationalStatus} /><Fact label="Condition" value={physical.condition || 'READY'} /><Fact label="Current Use" value={use} /><Fact label="Guest" value={current ? getGuestName(current) : 'No current guest'} /><Fact label="Departure" value={current ? `${formatStayDate(current.checkOut)} · ${current.expectedDepartureTime || '11:00'}` : '—'} /><Fact label="Next Reservation" value={next ? `${getReservationCode(next)} · ${formatStayRange(next.checkIn, next.checkOut, { year: false })}` : 'None scheduled'} /><Fact label="Next Arrival" value={next?.estimatedArrivalTime || '—'} /></dl>{current && <Link to={`/management/reservations/${current.id}`}>View Reservation</Link>}{physical.condition !== 'READY' && <div className="condition-actions"><button type="button" onClick={() => { updateRoomCondition(physical.id, 'CLEANING'); setMessage(`Room ${physical.roomNumber} marked Cleaning.`) }}>Mark Cleaning</button><button type="button" onClick={() => { updateRoomCondition(physical.id, 'READY'); setMessage(`Room ${physical.roomNumber} marked Ready.`) }}>Mark Ready</button></div>}</article>)}{!board.length && <EmptyState title="No rooms match this board" text="Adjust the hotel, room type, date, or quick filter." />}</section></>
}

function useReservationDialog(onClose) {
  const dialogRef = useRef(null)
  useEffect(() => {
    const previousOverflow = document.body.style.overflow
    const previousFocus = document.activeElement
    document.body.style.overflow = 'hidden'
    dialogRef.current?.focus()
    const closeOnEscape = (event) => { if (event.key === 'Escape') onClose() }
    document.addEventListener('keydown', closeOnEscape)
    return () => { document.body.style.overflow = previousOverflow; document.removeEventListener('keydown', closeOnEscape); previousFocus?.focus?.() }
  }, [onClose])
  return dialogRef
}
function ActionDialog({ title, confirmLabel, danger, reservation, onClose, onConfirm }) {
  const dialogRef = useReservationDialog(onClose); const [reason, setReason] = useState(''); const [note, setNote] = useState(''); const [error, setError] = useState('')
  return <div className="reservation-dialog-backdrop" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><section ref={dialogRef} tabIndex="-1" className="reservation-dialog" role="dialog" aria-modal="true" aria-labelledby="reservation-dialog-title"><button className="dialog-close" type="button" aria-label="Close" onClick={onClose}><X size={18} /></button><span>Reservation action</span><h2 id="reservation-dialog-title">{title}</h2><p>{getReservationCode(reservation)} · {formatStayRange(reservation.checkIn, reservation.checkOut)}</p><ManagementSelect label="Reason" required value={reason} options={[allOption('Select a reason'), ...['Change of Plans', 'Booked Wrong Dates', 'Found Alternative', 'Travel Cancelled', 'Other'].map((value) => option(value))]} onChange={(value) => { setReason(value); setError('') }} /><Field label="Optional Notes"><textarea rows="3" value={note} onChange={(e) => setNote(e.target.value)} /></Field>{error && <p className="reservation-error" role="alert">{error}</p>}<div className="dialog-actions"><button type="button" onClick={onClose}>Keep Reservation</button><button className={danger ? 'danger' : ''} type="button" onClick={() => reason ? onConfirm({ reason, note }) : setError('Select a cancellation reason.')}>{confirmLabel}</button></div></section></div>
}
function ConfirmDialog({ title, text, confirm, onClose, onConfirm }) {
  const dialogRef = useReservationDialog(onClose)
  return <div className="reservation-dialog-backdrop" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><section ref={dialogRef} tabIndex="-1" className="reservation-dialog" role="dialog" aria-modal="true" aria-labelledby="reservation-confirm-title"><CircleAlert size={25} /><h2 id="reservation-confirm-title">{title}</h2><p>{text}</p><div className="dialog-actions"><button type="button" onClick={onClose}>Go Back</button><button type="button" onClick={onConfirm}>{confirm}</button></div></section></div>
}
function StatusBadge({ value }) { return <span className={`reservation-badge reservation-badge--${String(value).toLowerCase().replaceAll(' ', '-').replaceAll('_', '-')}`}>{String(value).replaceAll('_', ' ')}</span> }
function DetailCard({ title, children }) { return <article className="reservation-panel detail-card"><h2>{title}</h2>{children}</article> }
function Fact({ label, value }) { return <div><dt>{label}</dt><dd>{value ?? '—'}</dd></div> }
function Field({ label, children }) { return <label className="reservation-field"><span>{label}</span>{children}</label> }
function EmptyState({ title, text }) { return <div className="reservation-empty"><BedDouble size={23} /><h3>{title}</h3><p>{text}</p></div> }
function NotFound() { return <section className="reservation-management"><div className="reservation-empty"><CircleAlert size={28} /><h1>Reservation not found</h1><Link to="/management/reservations">Back to Reservations</Link></div></section> }
